'use client';

import { useMemo, useState } from 'react';
import Link from 'next/link';
import { Inter, Space_Grotesk } from 'next/font/google';
import { FaArrowLeft, FaBoxesStacked, FaLocationDot, FaShieldHeart, FaTruckFast } from 'react-icons/fa6';

import { driverOptions, poolMatches } from '@/lib/demo-data';

const heading = Space_Grotesk({ subsets: ['latin'], weight: ['500', '700'] });
const body = Inter({ subsets: ['latin'], weight: ['400', '500', '600'] });

const truckTypes = ['Mini Truck', 'Medium Truck', 'Full Truck', 'Trailer', 'Tempo'];

export default function ConsumerPortal() {
  const [selectedTruck, setSelectedTruck] = useState('Medium Truck');
  const [selectedDriver, setSelectedDriver] = useState(driverOptions[0]?.id ?? '');

  const rankedDrivers = useMemo(
    () =>
      [...driverOptions]
        .filter((driver) => selectedTruck === 'All' || driver.truckType === selectedTruck)
        .sort((a, b) => b.rating - a.rating || b.points - a.points),
    [selectedTruck],
  );

  return (
    <div className="min-h-screen bg-[radial-gradient(circle_at_top,_rgba(236,201,75,0.18),_transparent_35%),linear-gradient(180deg,_#0f172a_0%,_#111827_45%,_#030712_100%)] text-white">
      <div className="mx-auto max-w-7xl px-4 py-10 sm:px-6 lg:px-8">
        <div className="mb-8 flex items-center justify-between">
          <Link href="/get-started" className={`${body.className} inline-flex items-center gap-3 text-sm text-slate-300 transition hover:text-amber-300`}>
            <FaArrowLeft className="h-4 w-4" />
            Back to role selection
          </Link>
          <div className={`${body.className} rounded-full border border-amber-300/20 bg-amber-300/10 px-4 py-2 text-sm text-amber-100`}>
            Customer login, booking, ranking, and pooling demo
          </div>
        </div>

        <section className="grid gap-6 lg:grid-cols-[1.3fr_0.9fr]">
          <div className="rounded-[32px] border border-white/10 bg-white/5 p-8 shadow-2xl shadow-black/20 backdrop-blur">
            <p className={`${body.className} mb-3 text-sm uppercase tracking-[0.25em] text-amber-200/80`}>AQ Logistics Customer Portal</p>
            <h1 className={`${heading.className} max-w-3xl text-4xl font-bold leading-tight sm:text-5xl`}>
              Book trucks like a marketplace, but rank drivers on safety, reliability, and real delivery history.
            </h1>
            <p className={`${body.className} mt-4 max-w-2xl text-base text-slate-300`}>
              The customer flow supports secure sign-up and login, truck-type selection, ranked driver discovery, delivery safety notes, and backend truck-pooling suggestions to save fuel without exposing routing complexity on the storefront.
            </p>

            <div className="mt-8 grid gap-4 md:grid-cols-3">
              <div className="rounded-3xl border border-white/10 bg-slate-950/40 p-5">
                <FaTruckFast className="mb-4 h-6 w-6 text-amber-300" />
                <h2 className={`${heading.className} text-lg font-semibold`}>Truck Selection</h2>
                <p className={`${body.className} mt-2 text-sm text-slate-300`}>Customers choose vehicle class first, then compare drivers assigned to matching trucks.</p>
              </div>
              <div className="rounded-3xl border border-white/10 bg-slate-950/40 p-5">
                <FaShieldHeart className="mb-4 h-6 w-6 text-amber-300" />
                <h2 className={`${heading.className} text-lg font-semibold`}>Secure Profiles</h2>
                <p className={`${body.className} mt-2 text-sm text-slate-300`}>Verified IDs, driver points, historical ratings, and cargo-care notes shape the listing order.</p>
              </div>
              <div className="rounded-3xl border border-white/10 bg-slate-950/40 p-5">
                <FaBoxesStacked className="mb-4 h-6 w-6 text-amber-300" />
                <h2 className={`${heading.className} text-lg font-semibold`}>Pool-Ready Routing</h2>
                <p className={`${body.className} mt-2 text-sm text-slate-300`}>Nearby orders are grouped in the backend when timing and capacity align, improving fuel efficiency.</p>
              </div>
            </div>
          </div>

          <div className="rounded-[32px] border border-amber-300/20 bg-slate-950/70 p-8">
            <h2 className={`${heading.className} text-2xl font-semibold text-amber-100`}>Customer Account Flow</h2>
            <div className={`${body.className} mt-5 space-y-4 text-sm text-slate-300`}>
              <div className="rounded-2xl border border-white/10 bg-white/5 p-4">
                <div className="font-semibold text-white">1. Sign up as customer</div>
                <div className="mt-1">Email, phone, exact pickup and drop details, and case-sensitive credentials are validated before account creation.</div>
              </div>
              <div className="rounded-2xl border border-white/10 bg-white/5 p-4">
                <div className="font-semibold text-white">2. Request a truck</div>
                <div className="mt-1">Select truck type, goods category, timing, and service notes. The backend estimates quote and truck suitability.</div>
              </div>
              <div className="rounded-2xl border border-white/10 bg-white/5 p-4">
                <div className="font-semibold text-white">3. Choose from rankings</div>
                <div className="mt-1">Customers compare live driver rankings, safety protocols, fixed income bands, and previous performance before booking.</div>
              </div>
            </div>
          </div>
        </section>

        <section className="mt-8 grid gap-6 xl:grid-cols-[1.1fr_0.9fr]">
          <div className="rounded-[32px] border border-white/10 bg-white/5 p-8 backdrop-blur">
            <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
              <div>
                <h2 className={`${heading.className} text-3xl font-semibold`}>Ranked Drivers</h2>
                <p className={`${body.className} mt-2 text-sm text-slate-300`}>Choose a truck class to filter the ranked driver list.</p>
              </div>
              <select
                value={selectedTruck}
                onChange={(event) => setSelectedTruck(event.target.value)}
                className={`${body.className} rounded-2xl border border-white/10 bg-slate-950 px-4 py-3 text-sm text-white outline-none`}
              >
                {truckTypes.map((truckType) => (
                  <option key={truckType} value={truckType}>
                    {truckType}
                  </option>
                ))}
              </select>
            </div>

            <div className="mt-6 space-y-4">
              {rankedDrivers.map((driver) => (
                <button
                  key={driver.id}
                  onClick={() => setSelectedDriver(driver.id)}
                  className={`w-full rounded-3xl border p-5 text-left transition ${
                    selectedDriver === driver.id
                      ? 'border-amber-300/60 bg-amber-300/10'
                      : 'border-white/10 bg-slate-950/40 hover:border-white/20'
                  }`}
                >
                  <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
                    <div>
                      <div className={`${heading.className} text-xl font-semibold`}>{driver.name}</div>
                      <div className={`${body.className} mt-1 text-sm text-slate-300`}>
                        {driver.truckType} • {driver.truckId} • {driver.region}
                      </div>
                    </div>
                    <div className={`${body.className} flex flex-wrap gap-3 text-sm text-slate-200`}>
                      <span className="rounded-full bg-emerald-400/10 px-3 py-1 text-emerald-200">Rating {driver.rating}</span>
                      <span className="rounded-full bg-sky-400/10 px-3 py-1 text-sky-200">Predicted {driver.predictedRating}</span>
                      <span className="rounded-full bg-violet-400/10 px-3 py-1 text-violet-200">{driver.points} points</span>
                    </div>
                  </div>
                  <p className={`${body.className} mt-4 text-sm text-slate-300`}>{driver.safety}</p>
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-6">
            <div className="rounded-[32px] border border-white/10 bg-slate-950/70 p-8">
              <h2 className={`${heading.className} text-2xl font-semibold`}>Selected Driver Snapshot</h2>
              {rankedDrivers
                .filter((driver) => driver.id === selectedDriver)
                .map((driver) => (
                  <div key={driver.id} className={`${body.className} mt-5 space-y-4 text-sm text-slate-300`}>
                    <div className="rounded-2xl border border-white/10 bg-white/5 p-4">
                      <div className="text-white">{driver.name}</div>
                      <div className="mt-1">ETA {driver.etaHours} hours • {driver.trips} completed trips • Fixed driver income Rs. {driver.fixedIncome.toLocaleString()}</div>
                    </div>
                    <div className="rounded-2xl border border-white/10 bg-white/5 p-4">
                      <div className="text-white">Why this driver ranks high</div>
                      <div className="mt-1">High customer rating, strong predicted score from travel history, and consistent cargo-safety feedback.</div>
                    </div>
                    <div className="rounded-2xl border border-white/10 bg-white/5 p-4">
                      <div className="text-white">Goods safety coverage</div>
                      <div className="mt-1">Loading proof, unloading proof, route check-ins, verified driver identity, and sealed handoff checklist.</div>
                    </div>
                  </div>
                ))}
            </div>

            <div className="rounded-[32px] border border-emerald-300/20 bg-emerald-400/5 p-8">
              <div className="flex items-center gap-3">
                <FaLocationDot className="h-5 w-5 text-emerald-300" />
                <h2 className={`${heading.className} text-2xl font-semibold text-emerald-100`}>Truck-Pooling Suggestions</h2>
              </div>
              <div className="mt-5 space-y-4">
                {poolMatches.map((match) => (
                  <div key={match.id} className="rounded-2xl border border-emerald-200/15 bg-slate-950/50 p-4">
                    <div className={`${heading.className} text-lg font-medium text-white`}>{match.route}</div>
                    <div className={`${body.className} mt-2 text-sm text-slate-300`}>{match.timing}</div>
                    <div className={`${body.className} mt-1 text-sm text-emerald-200`}>{match.fuelSaving}</div>
                    <div className={`${body.className} mt-1 text-sm text-slate-300`}>{match.compatibility}</div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}
